// Changes: Lower if statements and expressions, merging paths that continue.
IrOperand lower_if(Ctx* ctx,
                   IrFunctionId function_id,
                   IrBlockId* block_id,
                   AstNode* node) {
  AstNode* condition_node = ast_node_child(ctx, node, AST_IF_COND);
  IrOperand condition =
      lower_expression(ctx, function_id, block_id, condition_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrBlockId then_block = ir_add_block(ctx, function_id);
  IrBlockId else_block = ir_add_block(ctx, function_id);
  emit_branch(ctx, function_id, *block_id, condition, then_block, else_block);

  AstNode* then_node = ast_node_child(ctx, node, AST_IF_THEN);
  AstNode* else_node = ast_node_child(ctx, node, AST_IF_ELSE);
  IrOperand then_value =
      lower_statement(ctx, function_id, &then_block, then_node);
  IrOperand else_value =
      lower_statement(ctx, function_id, &else_block, else_node);

  // A branch ending in return contributes no edge or value to the join.
  if (then_block == IR_INVALID_ID) {
    *block_id = else_block;
    return else_value;
  }
  if (else_block == IR_INVALID_ID) {
    *block_id = then_block;
    return then_value;
  }

  IrType type = ast_to_ir_data_type(ctx, ast_node_get_data_type(node));
  IrStackSlotId result = IR_INVALID_ID;

  // Both branches reach the join. Store their results in the same slot.
  if (type != IR_UNIT) {
    result = ir_add_slot(ctx, function_id, "$if", type);
    emit_store(ctx, function_id, then_block, result, then_value);
    emit_store(ctx, function_id, else_block, result, else_value);
  }

  *block_id = ir_add_block(ctx, function_id);
  emit_jump(ctx, function_id, then_block, *block_id);
  emit_jump(ctx, function_id, else_block, *block_id);

  return type == IR_UNIT ? unit_operand()
                         : emit_load(ctx, function_id, *block_id, result, type);
}

