// Changes: Lower a while loop with a separate condition block and back edge.
IrOperand lower_while(Ctx* ctx,
                      IrFunctionId function_id,
                      IrBlockId* block_id,
                      AstNode* node) {
  // The back edge targets the start of condition evaluation.
  IrBlockId head = ir_add_block(ctx, function_id);
  emit_jump(ctx, function_id, *block_id, head);
  *block_id = head;

  AstNode* condition_node = ast_node_child(ctx, node, AST_WHILE_COND);
  IrOperand condition =
      lower_expression(ctx, function_id, block_id, condition_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrBlockId body_block = ir_add_block(ctx, function_id);
  IrBlockId exit_block = ir_add_block(ctx, function_id);
  emit_branch(ctx, function_id, *block_id, condition, body_block, exit_block);

  AstNode* body = ast_node_child(ctx, node, AST_WHILE_BODY);
  lower_statement(ctx, function_id, &body_block, body);
  if (body_block != IR_INVALID_ID)
    emit_jump(ctx, function_id, body_block, head);

  *block_id = exit_block;
  return unit_operand();
}

