// Changes: Evaluate the right side of a Boolean operation only when needed.
IrOperand lower_logical(Ctx* ctx,
                        IrFunctionId function_id,
                        IrBlockId* block_id,
                        AstNode* node) {
  AstNode* left_node = ast_node_child(ctx, node, AST_BINARY_LEFT);
  IrOperand left = lower_expression(ctx, function_id, block_id, left_node);
  if (*block_id == IR_INVALID_ID)
    return unit_operand();

  IrBlockId left_block = *block_id;
  IrBlockId right_entry = ir_add_block(ctx, function_id);
  IrBlockId right_block = right_entry;
  AstNode* right_node = ast_node_child(ctx, node, AST_BINARY_RIGHT);
  IrOperand right =
      lower_expression(ctx, function_id, &right_block, right_node);

  // AND skips the right operand when false. OR skips it when true.
  bool is_and = ast_node_get_type(node) == AST_NODE_AND;
  *block_id = ir_add_block(ctx, function_id);
  IrBlockId true_target = is_and ? right_entry : *block_id;
  IrBlockId false_target = is_and ? *block_id : right_entry;
  emit_branch(ctx, function_id, left_block, left, true_target, false_target);

  if (right_block == IR_INVALID_ID)
    return bool_operand(!is_and);

  IrStackSlotId result = ir_add_slot(ctx, function_id, "$logical", IR_BOOL);
  emit_store(ctx, function_id, left_block, result, bool_operand(!is_and));
  emit_store(ctx, function_id, right_block, result, right);
  emit_jump(ctx, function_id, right_block, *block_id);

  return emit_load(ctx, function_id, *block_id, result, IR_BOOL);
}
